export const CUES = [{"t": 4.0, "end": 11.52, "lines": [{"t0": 4.0, "t1": 7.9, "text": "Nine thousand years ago, in a village in central China,"}, {"t0": 7.9, "t1": 12.12, "text": "someone made a flute from the wing bone of a crane."}]}, {"t": 20.5, "end": 22.06, "lines": [{"t0": 20.5, "t1": 22.66, "text": "It can still be played."}]}, {"t": 25.1, "end": 34.68, "lines": [{"t0": 25.1, "t1": 28.99, "text": "Along two great rivers, people began to farm."}, {"t0": 28.85, "t1": 32.22, "text": "Millet by the Yellow River, in the north."}, {"t0": 32.08, "t1": 35.28, "text": "Rice along the Yangtze, in the south."}]}, {"t": 37.1, "end": 42.77, "lines": [{"t0": 37.1, "t1": 41.66, "text": "And they learned to unwind a silk moth's cocoon into one long,"}, {"t0": 41.66, "t1": 43.37, "text": "shining thread."}]}, {"t": 47.7, "end": 55.67, "lines": [{"t0": 47.7, "t1": 50.24, "text": "More than three thousand years ago,"}, {"t0": 50.24, "t1": 56.27, "text": "Shang kings ruled the Yellow River plain, and cast great vessels of bronze."}]}, {"t": 59.2, "end": 66.25, "lines": [{"t0": 59.2, "t1": 61.17, "text": "To question their ancestors,"}, {"t0": 61.17, "t1": 66.85, "text": "they held a red-hot rod to bones and turtle shells, and read the cracks."}]}, {"t": 68.7, "end": 72.62, "lines": [{"t0": 68.7, "t1": 73.22, "text": "Then they carved the question, and the answer, beside them."}]}, {"t": 75.6, "end": 81.99, "lines": [{"t0": 75.6, "t1": 78.61, "text": "It is the oldest Chinese writing we know,"}, {"t0": 78.61, "t1": 82.59, "text": "and many of its signs can still be read today."}]}, {"t": 88.0, "end": 94.57, "lines": [{"t0": 88.0, "t1": 90.92, "text": "Far to the southwest, at Sanxingdui,"}, {"t0": 90.92, "t1": 95.17, "text": "others cast bronze faces with eyes on stalks."}]}, {"t": 98.5, "end": 105.8, "lines": [{"t0": 98.5, "t1": 102.6, "text": "The Zhou kings who came next claimed the Mandate of Heaven:"}, {"t0": 102.6, "t1": 106.4, "text": "a right to rule, which heaven could take away."}]}, {"t": 107.8, "end": 112.38, "lines": [{"t0": 107.8, "t1": 109.3, "text": "As their power faded,"}, {"t0": 109.3, "t1": 112.98, "text": "rival states fought for five hundred years."}]}, {"t": 115.4, "end": 122.84, "lines": [{"t0": 115.4, "t1": 118.89, "text": "And thinkers argued about how to live."}, {"t0": 118.75, "t1": 123.44, "text": "Confucius taught respect, learning, and duty to family."}]}, {"t": 124.5, "end": 130.05, "lines": [{"t0": 124.5, "t1": 126.52, "text": "Daoists said: be like water,"}, {"t0": 126.52, "t1": 130.65, "text": "which yields to everything, and wears away stone."}]}, {"t": 131.6, "end": 136.81, "lines": [{"t0": 131.6, "t1": 137.41, "text": "And Sunzi wrote that the greatest victory is the one won without a fight."}]}, {"t": 140.8, "end": 149.51, "lines": [{"t0": 140.8, "t1": 146.28, "text": "In 221 BCE, the king of Qin conquered the last of his rivals,"}, {"t0": 146.28, "t1": 150.11, "text": "and named himself the First Emperor."}]}, {"t": 151.5, "end": 158.66, "lines": [{"t0": 151.5, "t1": 155.78, "text": "He decreed one script, one coinage, one set of weights,"}, {"t0": 155.78, "t1": 159.26, "text": "even one width for every cart's axle."}]}, {"t": 160.7, "end": 164.85, "lines": [{"t0": 160.7, "t1": 165.45, "text": "He joined older walls into one long wall in the north."}]}, {"t": 167.2, "end": 173.28, "lines": [{"t0": 167.2, "t1": 170.13, "text": "And he was buried with an army of clay:"}, {"t0": 170.13, "t1": 173.88, "text": "thousands of soldiers, no two faces alike."}]}, {"t": 175.7, "end": 179.75, "lines": [{"t0": 175.7, "t1": 180.35, "text": "Farmers found them in 1974, digging a well."}]}, {"t": 182.0, "end": 184.85, "lines": [{"t0": 182.0, "t1": 185.45, "text": "His dynasty lasted fifteen years."}]}, {"t": 188.8, "end": 196.93, "lines": [{"t0": 188.8, "t1": 193.66, "text": "The Han dynasty that followed lasted four hundred years."}, {"t0": 193.52, "t1": 197.53, "text": "Most Chinese people still call themselves Han."}]}, {"t": 198.9, "end": 205.71, "lines": [{"t0": 198.9, "t1": 202.78, "text": "The envoy Zhang Qian crossed the deserts to the west,"}, {"t0": 202.78, "t1": 206.31, "text": "and trade followed, along the Silk Road."}]}, {"t": 207.4, "end": 213.49, "lines": [{"t0": 207.4, "t1": 209.41, "text": "Silk went west."}, {"t0": 209.27, "t1": 214.09, "text": "Horses, grapes and glass came east, and later, Buddhism."}]}, {"t": 216.4, "end": 224.1, "lines": [{"t0": 216.4, "t1": 221.45, "text": "Han craftsmen made paper, from bark, hemp and old rags."}, {"t0": 221.31, "t1": 224.7, "text": "This whole little world is made of it."}]}, {"t": 227.1, "end": 235.35, "lines": [{"t0": 227.1, "t1": 231.34, "text": "And Zhang Heng built a jar to detect distant earthquakes:"}, {"t0": 231.34, "t1": 235.95, "text": "a ball would drop from a dragon's mouth into a toad's."}]}, {"t": 240.4, "end": 247.33, "lines": [{"t0": 240.4, "t1": 244.24, "text": "An old novel begins: the empire, long divided,"}, {"t0": 244.24, "t1": 247.93, "text": "must unite; long united, must divide."}]}, {"t": 249.3, "end": 255.57, "lines": [{"t0": 249.3, "t1": 253.9, "text": "After the Han, it stayed divided for almost four hundred years,"}, {"t0": 253.9, "t1": 256.17, "text": "and Buddhism took root."}]}, {"t": 259.6, "end": 265.61, "lines": [{"t0": 259.6, "t1": 263.16, "text": "The Sui reunited it, and dug the Grand Canal,"}, {"t0": 263.16, "t1": 266.21, "text": "still the longest in the world."}]}, {"t": 267.6, "end": 274.17, "lines": [{"t0": 267.6, "t1": 270.55, "text": "Officials were chosen by written exams,"}, {"t0": 270.55, "t1": 274.77, "text": "a system that would last thirteen hundred years."}]}, {"t": 277.2, "end": 285.05, "lines": [{"t0": 277.2, "t1": 280.04, "text": "Under the Tang, the capital, Chang'an,"}, {"t0": 280.04, "t1": 285.65, "text": "held perhaps a million people, and merchants from as far as Persia."}]}, {"t": 287.0, "end": 292.98, "lines": [{"t0": 287.0, "t1": 293.58, "text": "Wu Zetian became the only woman to rule China as emperor in her own name."}]}, {"t": 296.0, "end": 300.82, "lines": [{"t0": 296.0, "t1": 301.42, "text": "And Li Bai wrote a poem that every child in China still knows."}]}, {"t": 303.2, "end": 312.78, "lines": [{"t0": 303.2, "t1": 305.6, "text": "Moonlight before my bed."}, {"t0": 305.46, "t1": 308.53, "text": "I took it for frost on the ground."}, {"t0": 308.39, "t1": 310.72, "text": "I raise my head to the bright moon,"}, {"t0": 310.72, "t1": 313.38, "text": "and lower it, thinking of home."}]}, {"t": 317.8, "end": 321.67, "lines": [{"t0": 317.8, "t1": 322.27, "text": "Under the Song, cities boomed, and so did invention."}]}, {"t": 323.7, "end": 329.2, "lines": [{"t0": 323.7, "t1": 329.8, "text": "Alchemists looking for the elixir of eternal life had found gunpowder instead."}]}, {"t": 332.2, "end": 335.25, "lines": [{"t0": 332.2, "t1": 335.85, "text": "The Song made it into rockets, and fireworks."}]}, {"t": 340.2, "end": 345.06, "lines": [{"t0": 340.2, "t1": 342.94, "text": "Sailors steered by compass."}, {"t0": 342.8, "t1": 345.66, "text": "Merchants paid with paper money."}]}, {"t": 346.9, "end": 352.43, "lines": [{"t0": 346.9, "t1": 349.77, "text": "And Bi Sheng printed with movable type,"}, {"t0": 349.77, "t1": 353.03, "text": "four hundred years before Gutenberg."}]}, {"t": 356.4, "end": 364.88, "lines": [{"t0": 356.4, "t1": 360.21, "text": "In 1279, the Mongols conquered all of China,"}, {"t0": 360.21, "t1": 365.48, "text": "and Kublai Khan ruled from where Beijing stands today."}]}, {"t": 366.9, "end": 372.91, "lines": [{"t0": 366.9, "t1": 371.57, "text": "Ninety years later, a peasant who had been a begging monk drove them out,"}, {"t0": 371.57, "t1": 373.51, "text": "and founded the Ming."}]}, {"t": 375.3, "end": 381.28, "lines": [{"t0": 375.3, "t1": 377.64, "text": "The Ming built the Forbidden City,"}, {"t0": 377.64, "t1": 381.88, "text": "and most of the Great Wall that people walk on today."}]}, {"t": 384.3, "end": 392.05, "lines": [{"t0": 384.3, "t1": 388.21, "text": "From 1405, Admiral Zheng He sailed seven times,"}, {"t0": 388.21, "t1": 392.65, "text": "with hundreds of ships, as far as East Africa."}]}, {"t": 394.4, "end": 401.28, "lines": [{"t0": 394.4, "t1": 397.67, "text": "One voyage brought back a giraffe."}, {"t0": 397.53, "t1": 401.88, "text": "The court took it for a qilin, a creature of legend."}]}, {"t": 405.3, "end": 411.77, "lines": [{"t0": 405.3, "t1": 408.31, "text": "In 1644, the Manchus took Beijing,"}, {"t0": 408.31, "t1": 412.37, "text": "and founded the last dynasty, the Qing."}]}, {"t": 413.8, "end": 419.17, "lines": [{"t0": 413.8, "t1": 416.04, "text": "With new crops from the Americas,"}, {"t0": 416.04, "t1": 419.77, "text": "the population grew past four hundred million."}]}, {"t": 421.6, "end": 426.55, "lines": [{"t0": 421.6, "t1": 423.58, "text": "Europe craved Chinese tea,"}, {"t0": 423.58, "t1": 427.15, "text": "silk and porcelain, and paid in silver."}]}, {"t": 428.5, "end": 437.06, "lines": [{"t0": 428.5, "t1": 433.31, "text": "To win the silver back, British merchants smuggled in opium."}, {"t0": 433.17, "t1": 437.66, "text": "When China destroyed it, Britain went to war, and won."}]}, {"t": 439.5, "end": 446.2, "lines": [{"t0": 439.5, "t1": 441.58, "text": "More wars, unequal treaties,"}, {"t0": 441.58, "t1": 446.8, "text": "and a civil war that killed tens of millions shook the empire."}]}, {"t": 448.6, "end": 454.66, "lines": [{"t0": 448.6, "t1": 453.2, "text": "In 1912, the last emperor gave up the throne."}, {"t0": 453.06, "t1": 455.26, "text": "He was six years old."}]}, {"t": 458.6, "end": 466.68, "lines": [{"t0": 458.6, "t1": 463.29, "text": "The young republic was torn by warlords and civil war,"}, {"t0": 463.29, "t1": 467.28, "text": "and, from 1937, by invasion from Japan."}]}, {"t": 468.3, "end": 471.25, "lines": [{"t0": 468.3, "t1": 471.85, "text": "At least fourteen million Chinese people died."}]}, {"t": 474.3, "end": 481.25, "lines": [{"t0": 474.3, "t1": 478.26, "text": "In 1949, the Communists under Mao Zedong won,"}, {"t0": 478.26, "t1": 481.85, "text": "and founded the People's Republic."}]}, {"t": 484.2, "end": 488.59, "lines": [{"t0": 484.2, "t1": 489.19, "text": "Schools and clinics reached the villages, and lives grew longer."}]}, {"t": 491.0, "end": 497.97, "lines": [{"t0": 491.0, "t1": 494.87, "text": "But the Great Leap Forward, Mao's rush to industrialise,"}, {"t0": 494.87, "t1": 498.57, "text": "caused a famine that killed tens of millions."}]}, {"t": 500.4, "end": 507.24, "lines": [{"t0": 500.4, "t1": 505.0, "text": "In the Cultural Revolution, students were turned against their teachers,"}, {"t0": 505.0, "t1": 507.84, "text": "and children against their parents."}]}, {"t": 510.6, "end": 521.83, "lines": [{"t0": 510.6, "t1": 515.72, "text": "Even then, following a clue in a medical book sixteen hundred years old,"}, {"t0": 515.72, "t1": 519.58, "text": "Tu Youyou's team found a new cure for malaria."}, {"t0": 519.44, "t1": 522.43, "text": "It has saved millions of lives."}]}, {"t": 525.8, "end": 532.5, "lines": [{"t0": 525.8, "t1": 528.64, "text": "From 1978, under Deng Xiaoping,"}, {"t0": 528.64, "t1": 533.1, "text": "China opened to the world, and to markets."}]}, {"t": 534.5, "end": 540.08, "lines": [{"t0": 534.5, "t1": 540.68, "text": "Shenzhen grew from a small border town into a city of almost eighteen million."}]}, {"t": 542.5, "end": 549.79, "lines": [{"t0": 542.5, "t1": 546.69, "text": "Some eight hundred million people escaped extreme poverty:"}, {"t0": 546.69, "t1": 550.39, "text": "the largest escape from poverty in history."}]}, {"t": 552.8, "end": 558.24, "lines": [{"t0": 552.8, "t1": 558.84, "text": "In 1989, protests in Tiananmen Square were crushed by the army."}]}, {"t": 562.3, "end": 569.44, "lines": [{"t0": 562.3, "t1": 565.71, "text": "And light reached the farthest villages."}, {"t0": 565.57, "t1": 570.04, "text": "By 2015, almost every home had electricity."}]}, {"t": 575.4, "end": 579.33, "lines": [{"t0": 575.4, "t1": 579.93, "text": "Today, 1.4 billion people live in China."}]}, {"t": 580.9, "end": 591.56, "lines": [{"t0": 580.9, "t1": 584.71, "text": "Its high-speed railways, the first opened in 2008,"}, {"t0": 584.71, "t1": 592.16, "text": "now run for more than fifty thousand kilometres: more than the rest of the world together."}]}, {"t": 594.6, "end": 605.42, "lines": [{"t0": 594.6, "t1": 595.23, "text": "In 2019,"}, {"t0": 595.23, "t1": 601.12, "text": "a Chinese probe made the first landing on the far side of the Moon."}, {"t0": 600.98, "t1": 606.02, "text": "In 2024, another brought back the first rocks from there."}]}, {"t": 609.4, "end": 617.07, "lines": [{"t0": 609.4, "t1": 612.72, "text": "China burns more coal than any other country,"}, {"t0": 612.72, "t1": 617.67, "text": "and builds about half the world's new solar and wind power."}]}, {"t": 619.1, "end": 625.33, "lines": [{"t0": 619.1, "t1": 622.79, "text": "And its forests now cover a quarter of the land,"}, {"t0": 622.79, "t1": 625.93, "text": "twice as much as forty years ago."}]}, {"t": 629.3, "end": 634.09, "lines": [{"t0": 629.3, "t1": 632.54, "text": "From a bone flute to the far side of the Moon,"}, {"t0": 632.54, "t1": 634.69, "text": "it is one long thread."}]}, {"t": 639.1, "end": 644.42, "lines": [{"t0": 639.1, "t1": 641.85, "text": "Ahead, the paper is still blank."}, {"t0": 641.71, "t1": 645.02, "text": "The next part has not been written yet."}]}];
